#!/usr/bin/env python3
"""Frozen local-grader benchmark. Domain scores are weighted means of item grades."""
import argparse
import json
import re
import subprocess
import sys
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path
from threading import Lock

from research_sdk import Client

ROOT = Path(__file__).resolve().parent
SPEC = json.loads((ROOT / "grader_spec.json").read_text())
LOCK = Lock()
ALLOWED_IMPORTS = {"calendar", "collections", "datetime", "functools", "heapq", "itertools", "json", "math", "re"}

def extract_answer(text):
    matches = re.findall(r"<answer>(.*?)</answer>", text, flags=re.I | re.S)
    if matches:
        return matches[-1].strip()
    return text.strip()

def extract_code(text):
    fences = re.findall(r"```(?:python)?\s*(.*?)```", text, flags=re.I | re.S)
    if fences:
        return fences[-1].strip()
    return text.strip()

def run_impl(code, tests):
    script = r'''
import json, sys, builtins
ALLOWED = set(filter(None, sys.argv[2].split(",")))
def limited_import(name, globals=None, locals=None, fromlist=(), level=0):
    root = name.split(".")[0]
    if root not in ALLOWED:
        raise ImportError(name)
    return __import__(name, globals, locals, fromlist, level)
safe = {name: getattr(builtins, name) for name in (
    "abs","all","any","bool","dict","enumerate","float","int","len","list","max","min",
    "range","reversed","round","set","sorted","str","sum","tuple","zip","Exception",
    "ValueError","TypeError","KeyError","IndexError","StopIteration","isinstance",
    "issubclass","map","filter","divmod","pow","hex","oct","bin","iter","next",
    "hasattr","getattr","setattr","repr","format","slice","object","staticmethod",
    "classmethod","property","super","print","ord","chr")}
safe["__import__"] = limited_import
safe["True"] = True
safe["False"] = False
safe["None"] = None
code = sys.stdin.read()
ns = {"__builtins__": safe}
try:
    exec(code, ns, ns)
except Exception as exc:
    print(json.dumps({"ok": False, "error": "exec:"+type(exc).__name__}))
    raise SystemExit(0)
solve = ns.get("solve")
if not callable(solve):
    print(json.dumps({"ok": False, "error": "no-solve"}))
    raise SystemExit(0)
tests = json.loads(sys.argv[1])

def norm(v):
    if isinstance(v, tuple):
        return [norm(x) for x in v]
    if isinstance(v, list):
        return [norm(x) for x in v]
    return v

results = []
for args, expected in tests:
    try:
        got = solve(*args)
        results.append(norm(got) == norm(expected))
    except Exception:
        results.append(False)
print(json.dumps({"ok": True, "results": results}))
'''
    proc = subprocess.run(
        [sys.executable, "-c", script, json.dumps(tests), ",".join(sorted(ALLOWED_IMPORTS))],
        input=code.encode(),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        timeout=8,
    )
    if not proc.stdout:
        return []
    data = json.loads(proc.stdout.decode() or "{}")
    return data.get("results") or []

def grade_impl(item_id, text):
    code = extract_code(text)
    tests = SPEC["impl"][item_id]["tests"]
    try:
        results = run_impl(code, tests)
    except subprocess.TimeoutExpired:
        return {"score": 0.0, "answer_status": "answered", "preview": "timeout"}
    except Exception as exc:
        return {"score": 0.0, "answer_status": "answered", "preview": "grader-error:"+type(exc).__name__}
    if not results:
        return {"score": 0.0, "answer_status": "answered", "preview": code[:180]}
    score = sum(1 for r in results if r) / len(results)
    return {"score": score, "answer_status": "answered", "preview": code[:160], "passed": int(sum(results)), "n": len(results)}

def norm_stdout(s):
    lines = s.replace("\r\n", "\n").replace("\r", "\n").split("\n")
    lines = [ln.rstrip() for ln in lines]
    while lines and lines[-1] == "":
        lines.pop()
    return "\n".join(lines)

def grade_trace(item_id, text):
    ans = extract_answer(text)
    ok = norm_stdout(ans) == norm_stdout(SPEC["traces"][item_id]["stdout"])
    return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:180]}

def parse_number(s):
    t = s.strip().replace(",", "").replace("$", "")
    t = t.splitlines()[0].strip() if t else t
    t = t.replace(" ", "")
    if t.endswith("%"):
        try:
            return float(t[:-1]) / 100.0
        except ValueError:
            return None
    m = re.fullmatch(r"(-?\d+(?:\.\d+)?)/(-?\d+(?:\.\d+)?)", t)
    if m:
        den = float(m.group(2))
        if den == 0:
            return None
        return float(m.group(1)) / den
    try:
        return float(t)
    except ValueError:
        return None

def grade_answer(item_id, text):
    spec = SPEC["answers"][item_id]
    ans = extract_answer(text)
    if spec.get("mc") or spec.get("kind") == "mc":
        letter = re.sub(r"[^A-Za-z]", "", ans).upper()[:1]
        ok = letter == str(spec["value"]).strip().upper()
        return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:80]}
    alts = [str(a) for a in spec.get("alts", [])]
    if "value" in spec and str(spec["value"]) not in alts:
        alts.append(str(spec["value"]))
    collapsed = re.sub(r"\s+", "", ans).lower()
    if spec.get("kind") == "exact" or (alts and not spec.get("value")):
        ok = any(re.sub(r"\s+", "", a).lower() == collapsed for a in alts)
        return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:120]}
    if any(re.sub(r"\s+", "", a).lower() == collapsed for a in alts):
        return {"score": 1.0, "answer_status": "answered", "preview": ans[:120]}
    target = parse_number(str(spec.get("value", "")))
    got = parse_number(ans.splitlines()[0] if ans else "")
    ok = target is not None and got is not None and abs(got - target) <= 1e-9 * max(1.0, abs(target))
    if not ok:
        for alt in alts:
            token = re.sub(r"\s+", "", alt).lower()
            if len(token) > 2 and token in collapsed and len(collapsed) <= len(token) + 8:
                ok = True
                break
    return {"score": 1.0 if ok else 0.0, "answer_status": "answered", "preview": ans[:120]}

def word_count(text):
    return re.findall(r"[A-Za-z0-9']+", text)

def grade_checks(item_id, text):
    spec = SPEC["checks"][item_id]
    ans = extract_answer(text)
    lines = ans.splitlines()
    low = ans.lower()
    word_re = spec.get("word_regex", r"[A-Za-z0-9']+")
    words = re.findall(word_re, ans)
    checks = []
    if "n_lines" in spec:
        checks.append(len(lines) == spec["n_lines"])
    for idx, exact in spec.get("exact", {}).items():
        i = int(idx)
        checks.append(i < len(lines) and lines[i] == exact)
    for idx, prefix in spec.get("startswith", {}).items():
        i = int(idx)
        checks.append(i < len(lines) and lines[i].startswith(prefix))
    for needle in spec.get("contains", []):
        checks.append(str(needle).lower() in low)
    for idx, needle in spec.get("line_contains", {}).items():
        i = int(idx)
        checks.append(i < len(lines) and str(needle).lower() in lines[i].lower())
    for idx, needle in spec.get("line_contains_ci", {}).items():
        i = int(idx)
        checks.append(i < len(lines) and str(needle).lower() in lines[i].lower())
    for bad in list(spec.get("forbidden", [])) + list(spec.get("forbidden_substrings", [])):
        checks.append(str(bad).lower() not in low)
    if "word_count" in spec:
        lo, hi = spec["word_count"]
        checks.append(lo <= len(words) <= hi)
    for idx, bounds in spec.get("line_words", {}).items():
        i = int(idx)
        n = len(re.findall(word_re, lines[i])) if i < len(lines) else 0
        checks.append(bounds[0] <= n <= bounds[1])
    if "max_line_len" in spec:
        checks.append(bool(lines) and all(len(ln) <= spec["max_line_len"] for ln in lines))
    for word, count in spec.get("word_exact", {}).items():
        found = re.findall(r"\b" + re.escape(word) + r"\b", ans, flags=re.I)
        checks.append(len(found) == count)
    for word, count in spec.get("word_min", {}).items():
        found = re.findall(r"\b" + re.escape(word) + r"\b", ans, flags=re.I)
        checks.append(len(found) >= int(count))
    if not checks:
        return {"score": 0.0, "answer_status": "answered", "preview": ans[:160]}
    score = sum(1 for c in checks if c) / len(checks)
    return {"score": score, "answer_status": "answered", "preview": ans[:180], "passed": int(sum(checks)), "n": len(checks)}

def grade(item_id, text):
    if not text or not text.strip():
        return {"score": 0.0, "answer_status": "missing"}
    if item_id in SPEC.get("impl", {}):
        return grade_impl(item_id, text)
    if item_id in SPEC.get("traces", {}):
        return grade_trace(item_id, text)
    if item_id in SPEC.get("answers", {}):
        return grade_answer(item_id, text)
    if item_id in SPEC.get("checks", {}):
        return grade_checks(item_id, text)
    raise KeyError(item_id)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--context", required=True)
    parser.add_argument("--output", required=True)
    args = parser.parse_args()
    client = Client(args.context)
    manifest = json.loads((ROOT / "evaluation.json").read_text())
    prompts = {q["id"]: q["prompt"] for q in manifest["questions"]}
    out = Path(args.output)
    results = {}

    def persist():
        ordered = [results[it["id"]] for it in manifest["items"] if it["id"] in results]
        payload = json.dumps({"protocol_version": 1, "items": ordered})
        tmp = out.with_suffix(".partial.json")
        tmp.write_text(payload)
        tmp.replace(out)

    def run_one(item):
        iid = item["id"]
        cap = int(SPEC.get("tokens", {}).get(iid, 1536))
        def grader(text, iid=iid):
            return grade(iid, text)
        return client.item(
            iid,
            prompts[item["question_id"]],
            grader,
            max_tokens=cap,
            system="Be concise and exact. Follow the requested output format. Do not explain inside answer tags or code fences.",
        )

    pending = []
    for it in manifest["items"]:
        if it["id"] in client.completed_items:
            results[it["id"]] = client.completed_items[it["id"]]
        else:
            pending.append(it)
    persist()
    workers = 2
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures = {pool.submit(run_one, it): it["id"] for it in pending}
        for fut in as_completed(futures):
            row = fut.result()
            with LOCK:
                results[row["id"]] = row
                persist()
    missing = [it["id"] for it in manifest["items"] if it["id"] not in results]
    if missing:
        raise SystemExit("missing items: " + ",".join(missing))
    persist()

if __name__ == "__main__":
    main()
